syntax:
To enable polymorphism, declare functions in the base class as virtual.  Example:

```c++
class Base {
public:
  virtual void myFunction() { std::cout << "Base::myFunction()\n"; }
};

class Derived : public Base {
public:
  void myFunction() override { std::cout << "Derived::myFunction()\n"; }
};
```

`virtual` keyword makes the function virtual, allowing dynamic dispatch. `override` (C++11 and later) is a best practice to ensure the function is indeed overriding a virtual base function and catch potential errors at compile time.

code_example:
#include <iostream>
#include <vector>
class Animal {
public:
  virtual void speak() { std::cout << "Generic animal sound\n"; }
  virtual ~Animal() = default; // Important: virtual destructor for polymorphic classes
};
class Dog : public Animal {
public:
  void speak() override { std::cout << "Woof!\n"; }
};
class Cat : public Animal {
public:
  void speak() override { std::cout << "Meow!\n"; }
};
int main() {
  std::vector<Animal*> animals;
  animals.push_back(new Dog());
  animals.push_back(new Cat());
  for (Animal* animal : animals) {
    animal->speak(); // Polymorphic call - correct function is called at runtime
    delete animal;
  }
  return 0;
}
